insert into public.problems (id, title, statement, input_spec, output_spec, notes, examples, tags, rating, time_limit_ms, visibility) values (1232, 'Far Apart Nests', 'There are n free spots on a long branch at positions x_1 … x_n. k birds want to sit on different spots and stay as far from each other as possible. Choose the spots so that the smallest distance between two of the birds is as large as possible, and print that distance.', 'The first line contains n and k (2 ≤ k ≤ n ≤ 2·10^4). The second line contains n different integers (0 ≤ x_i ≤ 10^9).', 'Print the largest possible smallest distance.', '', '[{"input":"5 3\n1 2 8 4 9\n","output":"3"},{"input":"2 2\n0 1000000000\n","output":"1000000000"}]'::jsonb, array['binary search','greedy','sortings']::text[], 1900, 2000, 'public') on conflict (id) do nothing;
